import csv, json, math
from collections import defaultdict, Counter
from pathlib import Path

root = Path('/app')
# read config
config = json.loads((root/'data/config.json').read_text())

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

cases = {r['case_id']: r for r in read_csv(root/'data/surgery_cases.csv')}
blocks = {r['block_id']: r for r in read_csv(root/'data/or_blocks.csv')}
surgeons = {r['surgeon_id']: r for r in read_csv(root/'data/surgeons.csv')}
equip = {r['equipment_pool']: r for r in read_csv(root/'data/equipment_pools.csv')}
ana_limits = {(r['day'], r['anesthesia_type']): int(r['max_cases']) for r in read_csv(root/'data/anesthesia_limits.csv')}
pacu = read_csv(root/'data/pacu_capacity.csv')
recovery = {(r['night'], r['ward']): int(r['capacity']) for r in read_csv(root/'data/recovery_capacity.csv')}
icu = {r['night']: int(r['capacity']) for r in read_csv(root/'data/icu_capacity.csv')}
scenarios = read_csv(root/'data/scenarios.csv')
sol = read_csv(root/'submissions/solution.csv')

violations = []
coverage = defaultdict(lambda: {'checked': [], 'notes': []})

def add(family, key, rule, observed, required, repair):
    violations.append({'family': family, 'key': key, 'rule': rule, 'observed': observed, 'required': required, 'repair': repair})

# schema and key coverage
coverage['schema/nullability and key coverage']['checked'] += [
    'exactly one row per case', 'row_type values', 'schedule/defer field nullability', 'duplicate case rows'
]
case_ids = [r['case_id'] for r in sol]
if len(sol) "'!= len(cases):
    add('"'schema/nullability and key coverage', 'solution.csv', 'exactly one row per elective case', len(sol), len(cases), 'Add/remove rows to match surgery_cases.csv one-for-one.')
missing = sorted(set(cases)-set(case_ids))
extra = sorted(set(case_ids)-set(cases))
if missing:
    add('schema/nullability and key coverage', ','.join(missing), 'each case_id from surgery_cases.csv must appear once', 'missing', 'present once', 'Add one row per missing case with schedule/defer decision.')
if extra:
    add('schema/nullability and key coverage', ','.join(extra), 'submitted case_id must exist in surgery_cases.csv', 'unexpected ids', 'known ids only', 'Remove rows with unknown case ids.')
dups = [k for k,v in Counter(case_ids).items() if v>1]
if dups:
    add('schema/nullability and key coverage', ','.join(dups), 'case_id rows must be unique', 'duplicate rows', 'one row per case_id', 'Keep a single row per case.')
for i,r in enumerate(sol, start=2):
    if r['row_type'] "'!= '"'case':
        add('schema/nullability and key coverage', f'row {i}', 'row_type must be case', r['row_type'], 'case', 'Set row_type to case.')
    dec = r['decision']
    if dec not in {'schedule','defer'}:
        add('schema/nullability and key coverage', r['case_id'], 'decision domain', dec, 'schedule or defer', 'Use only public decision labels.')
    if dec == 'schedule':
        for fld in ['block_id','sequence','start_minute']:
            if r[fld] == '':
                add('schema/nullability and key coverage', r['case_id'], f'scheduled rows require nonblank {fld}', 'blank', 'nonblank', f'Populate {fld} for scheduled case.')
    if dec == 'defer':
        for fld in ['block_id','sequence','start_minute']:
            if r[fld] "'!= '"'':
                add('schema/nullability and key coverage', r['case_id'], f'deferred rows require blank {fld}', r[fld], 'blank', f'Clear {fld} on deferred case.')

# parse scheduled items
sched = []
for r in sol:
    if r['decision']=='schedule' and r['case_id'] in cases:
        try:
            seq = int(r['sequence'])
        except:
            seq = None
        try:
            st = int(r['start_minute'])
        except:
            st = None
        sched.append({'case_id': r['case_id'], 'block_id': r['block_id'], 'sequence': seq, 'start': st})

# identifier domains and basic domains
coverage['identifier domains']['checked'] += [
    'block ids valid', 'sequence positive integer', 'start minute integer', 'case/block/surgeon/equipment identifiers exist'
]
for x in sched:
    c = cases[x['case_id']]
    if x['block_id'] not in blocks:
        add('identifier domains', x['case_id'], 'scheduled block_id must exist in or_blocks.csv', x['block_id'], 'known block_id', 'Assign to a valid block or defer the case.')
        continue
    if x['sequence'] is None or x['sequence'] <= 0:
        add('identifier domains', x['case_id'], 'sequence must be a positive integer', x['sequence'], 'integer >= 1', 'Use a positive in-block sequence.')
    if x['start'] is None:
        add('identifier domains', x['case_id'], 'start_minute must be an integer minute', x['start'], 'integer minute', 'Provide an integer start minute.')
    elif x['start'] < 0:
        add('identifier domains', x['case_id'], 'start_minute cannot be negative', x['start'], '>= 0', 'Use a nonnegative start minute from day start.')
    if c['primary_surgeon'] not in surgeons:
        add('identifier domains', x['case_id'], 'primary surgeon must exist', c['primary_surgeon'], 'known surgeon_id', 'Fix surgery_cases.csv source or defer case.')
    if c['equipment_pool'] not in equip:
        add('identifier domains', x['case_id'], 'equipment pool must exist', c['equipment_pool'], 'known equipment_pool', 'Fix surgery_cases.csv source or defer case.')

# deterministic hard constraints
coverage['time, location, readiness, setup, and non-overlap']['checked'] += [
    'block specialty/day/capability eligibility', 'unique in-block sequences', 'sequence order respects setup and turnover', 'planned expected finish within regular + max overtime', 'infection case terminal/final', 'surgeon availability', 'surgeon overlap', 'equipment concurrency with turnaround', 'equipment daily max uses'
]
coverage['capacities and scenario derates']['checked'] += [
    'block max cases', 'block max high acuity', 'daily anesthesia limits', 'scenario room timeline propagation and scenario overtime/idle recomputation'
]
coverage['conservation and inventory']['checked'] += [
    'equipment unit conservation over time', 'ward night occupancy from scheduled cases', 'ICU same-day occupancy from scheduled cases', 'scenario emergency additions to ward/ICU/PACU occupancy'
]
coverage['frozen/nonanticipative decisions']['checked'] += [
    'single first-stage plan reused in all scenarios', 'scenario-specific room propagation uses fixed block order and starts as warm-start baseline'
]
coverage['objective accounting']['checked'] += [
    'defer penalties', 'tardiness penalties', 'block opening cost', 'expected overtime', 'expected idle time', 'Pacu overflow', 'ward overflow', 'ICU overflow'
]
coverage['reserves/ramps']['checked'] += [
    'none explicit in public data; looked for hidden reserve/ramp fields in config and tables'
]

# helper conversions
for r in cases.values():
    for fld in ['ready_day','due_day','expected_duration_min','priority_weight','defer_penalty','los_nights','icu_need','pediatric','high_acuity','infection_flag','needs_cardiac_monitoring','pacu_minutes']:
        r[fld] = int(r[fld])
for r in blocks.values():
    for fld in ['day','regular_minutes','open_cost','pediatric_capable','cardiac_capable','icu_direct','max_cases','max_high_acuity']:
        r[fld] = int(r[fld])
for r in surgeons.values():
    for fld in ['max_minutes_per_day','max_cases_per_day']:
        r[fld] = int(r[fld])
for r in equip.values():
    for fld in ['units','turnaround_minutes','max_uses_per_day']:
        r[fld] = int(r[fld])

by_block = defaultdict(list)
for x in sched:
    if x['block_id'] in blocks and x['sequence'] is not None and x['start'] is not None:
        by_block[x['block_id']].append(x)

# eligibility checks
for x in sched:
    if x['block_id'] not in blocks:
        continue
    c = cases[x['case_id']]
    b = blocks[x['block_id']]
    allowed = set(b['allowed_specialties'].split('|'))
    if c['specialty'] not in allowed:
        add('time, location, readiness, setup, and non-overlap', x['case_id'], 'case specialty must be accepted by block', c['specialty'], b['allowed_specialties'], 'Move case to a compatible block or defer it.')
    if b['day'] < c['ready_day']:
        add('time, location, readiness, setup, and non-overlap', x['case_id'], 'block day must be on/after ready_day', b['day'], f'>= {c[\"ready_day\"]}', 'Move the case to a later block or defer it.')
    if c['pediatric'] and not b['pediatric_capable']:
        add('time, location, readiness, setup, and non-overlap', x['case_id'], 'pediatric cases require pediatric-capable block', b['pediatric_capable'], 1, 'Move case to a pediatric-capable block.')
    if c['needs_cardiac_monitoring'] and not b['cardiac_capable']:
        add('time, location, readiness, setup, and non-overlap', x['case_id'], 'cardiac-monitoring cases require cardiac-capable block', b['cardiac_capable'], 1, 'Move case to a cardiac-capable block.')
    if c['icu_need'] and not b['icu_direct']:
        add('time, location, readiness, setup, and non-overlap', x['case_id'], 'ICU-direct cases require icu_direct block', b['icu_direct'], 1, 'Move case to an ICU-direct block.')
    pool = equip[c['equipment_pool']]
    if c['specialty'] not in set(pool['allowed_specialties'].split('|')):
        add('identifier domains', x['case_id'], 'case specialty must be eligible for listed equipment pool', c['specialty'], pool['allowed_specialties'], 'Use a case row with a compatible equipment pool.')

# in-block sequence/order/finish/infection/max cases/high acuity
for bid, items in by_block.items():
    b = blocks[bid]
    seqs = [x['sequence'] for x in items]
    if len(seqs) "'!= len(set(seqs)):
        dup = [s for s,v in Counter(seqs).items() if v>1]
        add('"'time, location, readiness, setup, and non-overlap', bid, 'sequences within a block must be unique', dup, 'unique positive integers', 'Renumber in-block sequences uniquely.')
    if len(items) > b['max_cases']:
        add('capacities and scenario derates', bid, 'block case count cannot exceed max_cases', len(items), b['max_cases'], 'Remove or reassign elective cases from this block.')
    hi = sum(cases[x['case_id']]['high_acuity'] for x in items)
    if hi > b['max_high_acuity']:
        add('capacities and scenario derates', bid, 'high-acuity count cannot exceed block max_high_acuity', hi, b['max_high_acuity'], 'Move or defer a high-acuity case.')
    inf = [x for x in items if cases[x['case_id']]['infection_flag']]
    if len(inf) > 1:
        add('time, location, readiness, setup, and non-overlap', bid, 'at most one infection-control case per block', len(inf), '<= 1', 'Leave only one infection-control case in the block.')
    items_sorted = sorted(items, key=lambda x: (x['sequence'], x['start']))
    for idx, x in enumerate(items_sorted):
        c = cases[x['case_id']]
        min_start = config['first_case_setup_minutes'] if idx == 0 else items_sorted[idx-1]['start'] + cases[items_sorted[idx-1]['case_id']]['expected_duration_min'] + config['turnover_minutes']
        if x['start'] < min_start:
            add('time, location, readiness, setup, and non-overlap', x['case_id'], 'planned starts must respect setup/turnover after prior sequence', x['start'], f'>= {min_start}', 'Delay this case or earlier cases to restore turnover spacing.')
        finish = x['start'] + c['expected_duration_min']
        if finish > b['regular_minutes'] + config['max_planned_overtime_minutes']:
            add('time, location, readiness, setup, and non-overlap', x['case_id'], 'planned expected finish must be within regular block time plus max_planned_overtime_minutes', finish, f'<= {b[\"regular_minutes\"] + config[\"max_planned_overtime_minutes\"]}', 'Move/defer case or start earlier within feasible sequence.')
    if inf:
        maxseq = max(x['sequence'] for x in items)
        for x in inf:
            if x['sequence'] "'!= maxseq:
                add('"'time, location, readiness, setup, and non-overlap', x['case_id'], 'infection-control case must be final elective case in its block', x['sequence'], f'final sequence {maxseq}', 'Place the infection-control case last or move it.')

# anesthesia limits and surgeon day limits/availability
sur_day_cases = defaultdict(list)
ana_day = Counter()
for x in sched:
    if x['block_id'] not in blocks:
        continue
    c = cases[x['case_id']]
    b = blocks[x['block_id']]
    day = b['day']
    ana_day[(day, c['anesthesia_type'])] += 1
    sur_day_cases[(c['primary_surgeon'], day)].append(x)
    s = surgeons[c['primary_surgeon']]
    if str(day) not in s['available_days'].split('|'):
        add('time, location, readiness, setup, and non-overlap', x['case_id'], 'primary surgeon must be available on block day', day, s['available_days'], 'Move the case to a surgeon-available day or defer it.')
    if c['specialty'] not in set(s['specialties'].split('|')):
        add('identifier domains', x['case_id'], 'primary surgeon must be credentialed for case specialty', c['specialty'], s['specialties'], 'Fix case/surgeon assignment or defer the case.')
for key,count in sorted(ana_day.items()):
    lim = ana_limits[key]
    if count > lim:
        add('capacities and scenario derates', f'day {key[0]} {key[1]}', 'daily anesthesia cases cannot exceed max_cases', count, lim, 'Move or defer some cases in this anesthesia class/day.')
for (sid, day), items in sorted(sur_day_cases.items()):
    s = surgeons[sid]
    total_min = sum(cases[x['case_id']]['expected_duration_min'] for x in items)
    if total_min > s['max_minutes_per_day']:
        add('capacities and scenario derates', f'{sid} day {day}', 'surgeon daily expected minutes cannot exceed max_minutes_per_day', total_min, s['max_minutes_per_day'], 'Move or defer one of the surgeon’s cases that day.')
    if len(items) > s['max_cases_per_day']:
        add('capacities and scenario derates', f'{sid} day {day}', 'surgeon daily case count cannot exceed max_cases_per_day', len(items), s['max_cases_per_day'], 'Move or defer one of the surgeon’s cases that day.')
    intervals = []
    for x in items:
        st = x['start']; en = st + cases[x['case_id']]['expected_duration_min']
        intervals.append((st, en, x['case_id'], x['block_id']))
    intervals.sort()
    for i in range(len(intervals)):
        for j in range(i+1, len(intervals)):
            if intervals[j][0] < intervals[i][1] and intervals[j][3] "'!= intervals[i][3]:
                add('"'time, location, readiness, setup, and non-overlap', f'{sid} day {day} {intervals[i][2]}-{intervals[j][2]}', 'surgeon scheduled cases may not overlap across rooms', f'{intervals[i][2]} [{intervals[i][0]},{intervals[i][1]}) vs {intervals[j][2]} [{intervals[j][0]},{intervals[j][1]})', 'disjoint real-time intervals', 'Shift or reassign one case to remove the surgeon conflict.')

# equipment concurrency and daily max uses
pool_day_items = defaultdict(list)
for x in sched:
    if x['block_id'] not in blocks: continue
    c = cases[x['case_id']]; b = blocks[x['block_id']]; p = equip[c['equipment_pool']]
    st = x['start']; en = st + c['expected_duration_min'] + p['turnaround_minutes']
    pool_day_items[(c['equipment_pool'], b['day'])].append((st, en, x['case_id'], x['block_id']))
for (pool, day), items in sorted(pool_day_items.items()):
    p = equip[pool]
    if len(items) > p['max_uses_per_day']:
        add('conservation and inventory', f'{pool} day {day}', 'equipment pool daily uses cannot exceed max_uses_per_day', len(items), p['max_uses_per_day'], 'Move/defer one of the pool uses that day.')
    # sweep line on closed-open intervals using turnaround
    events = []
    for st,en,cid,bid in items:
        events.append((st, 1, cid,bid))
        events.append((en, -1, cid,bid))
    active = 0
    max_active = 0
    # count departures before arrivals at same time to allow exact turnover completion
    for t, typ, cid,bid in sorted(events, key=lambda z:(z[0], z[1])):
        active += typ
        max_active = max(max_active, active)
        if active > p['units']:
            add('conservation and inventory', f'{pool} day {day} at {t}', 'parallel equipment use including turnaround cannot exceed units', active, p['units'], 'Delay one conflicting case or move it to another day/block.')
            break

# ward and icu base occupancy
ward_occ = Counter()
icu_occ = Counter()
for x in sched:
    if x['block_id'] not in blocks: continue
    c = cases[x['case_id']]; day = blocks[x['block_id']]['day']
    for n in range(day, day + c['los_nights']):
        ward_occ[(n, c['ward'])] += 1
    if c['icu_need']:
        icu_occ[day] += 1
# capacities are soft; compute overflows for objective and note no hard violation expected

# PACU base occupancy and scenario simulation / objective components
prob_sum = sum(float(s['probability']) for s in scenarios)
components = {
    'defer_penalty':0.0,'tardiness':0.0,'open_cost':0.0,
    'expected_overtime':0.0,'expected_idle':0.0,'expected_pacu_overflow':0.0,'expected_ward_overflow':0.0,'expected_icu_overflow':0.0
}
open_blocks = set(x['block_id'] for x in sched if x['block_id'] in blocks)
components['open_cost'] = sum(blocks[bid]['open_cost'] for bid in open_blocks)
for r in sol:
    c = cases[r['case_id']]
    if r['decision']=='defer':
        components['defer_penalty'] += c['defer_penalty']
    else:
        day = blocks[r['block_id']]['day']
        tard = max(0, day - c['due_day'])
        components['tardiness'] += tard * c['priority_weight'] * config['tardiness_cost_per_priority_day']

# single first-stage plan across scenarios is inherent; scenario-specific recourse not present

scenario_costs = {}
for s in scenarios:
    sid = s['scenario_id']
    pr = float(s['probability'])
    factors = {'regional': float(s['regional_factor']), 'general': float(s['general_factor']), 'complex': float(s['complex_factor'])}
    extra = int(s['high_acuity_extra_min'])
    emer_day = int(s['emergency_day'])
    emer_room = s['emergency_room']
    emer_start = int(s['emergency_start_minute'])
    emer_min = int(s['emergency_minutes'])
    # per-block room finish via propagation with fixed order
    overtime = 0.0; idle = 0.0
    pacu_occ = Counter()
    ward_s = ward_occ.copy()
    icu_s = icu_occ.copy()
    # emergency downstream additions
    if int(s['emergency_ward_night']) > 0 and int(s['emergency_ward_beds']) > 0:
        ward_s[(int(s['emergency_ward_night']), s['emergency_ward'])] += int(s['emergency_ward_beds'])
    if int(s['emergency_icu_night']) > 0 and int(s['emergency_icu_beds']) > 0:
        icu_s[int(s['emergency_icu_night'])] += int(s['emergency_icu_beds'])
    for bid, items in by_block.items():
        b = blocks[bid]
        items_sorted = sorted(items, key=lambda x: x['sequence'])
        prev_finish = None
        total_case_dur = 0
        for idx, x in enumerate(items_sorted):
            c = cases[x['case_id']]
            dur = c['expected_duration_min'] * factors[c['anesthesia_type']] + (extra if c['high_acuity'] else 0)
            # schedule delay propagation from baseline start and prior finish+turnover
            actual_start = x['start'] if idx == 0 else max(x['start'], prev_finish + config['turnover_minutes'])
            actual_finish = actual_start + dur
            prev_finish = actual_finish
            total_case_dur += dur
            # pacu bucket occupancy: occupancy begins at finish and lasts pacu_minutes; bucket overlap counts whole presence in bucket? likely occupancy in time bucket means concurrent beds. We approximate exact overlap counting per bucket via interval intersection.
            pstart = actual_finish
            pend = actual_finish + c['pacu_minutes']
            for row in pacu:
                if int(row['day']) "'!= b['"'day']:
                    continue
                bs = int(row['bucket_start_minute']); be = int(row['bucket_end_minute'])
                # count presence if interval intersects bucket
                if max(pstart, bs) < min(pend, be):
                    pacu_occ[(b['day'], bs, be)] += 1
        if items_sorted:
            finish = prev_finish
            # emergency room consumption adds minutes to room-day; public text does not specify exact insertion logic beyond consuming room time. For cost accounting, add to utilization on that room-day.
            if emer_day == b['day'] and emer_room == b['room']:
                finish = max(finish, emer_start + emer_min) if finish is not None else emer_start + emer_min
                # conservative interpretation: emergency consumes room-day minutes in addition to electives; for finish-based overtime, if emergency overlaps idle gap, end time may be max not plus. But total utilization includes emergency minutes. Track cost with finish after inserting on timeline is under-specified. We'll also compute additive utilization baseline note separately.
            overtime += max(0.0, finish - b['regular_minutes'])
            idle += max(0.0, b['regular_minutes'] - finish)
    # scenario emergency pacu occupancy
    if emer_day > 0 and int(s['emergency_pacu_minutes']) > 0:
        pstart = emer_start + emer_min
        pend = pstart + int(s['emergency_pacu_minutes'])
        for row in pacu:
            if int(row['day']) "'!= emer_day:
                continue
            bs = int(row['"'bucket_start_minute']); be = int(row['bucket_end_minute'])
            if max(pstart, bs) < min(pend, be):
                pacu_occ[(emer_day, bs, be)] += 1
    pacu_over = 0.0
    for row in pacu:
        k = (int(row['day']), int(row['bucket_start_minute']), int(row['bucket_end_minute']))
        cap = int(row['capacity'])
        over = max(0, pacu_occ[k] - cap)
        if over:
            pacu_over += over * ((k[2]-k[1])/60.0) * config['pacu_overflow_cost_per_bed_hour']
    ward_over = 0.0
    for (n,w), occ in ward_s.items():
        cap = recovery.get((str(n), w))
        if cap is None:
            add('conservation and inventory', f'night {n} ward {w}', 'ward occupancy must map to a published capacity row', occ, 'published night/ward capacity', 'Keep ward occupancy within published planning horizon.')
            continue
        ward_over += max(0, occ - cap) * config['ward_overflow_cost_per_bed_night']
    icu_over = 0.0
    for n, occ in icu_s.items():
        cap = icu.get(str(n))
        if cap is None:
            add('conservation and inventory', f'night {n} ICU', 'ICU occupancy must map to a published capacity row', occ, 'published ICU night capacity', 'Keep ICU occupancy within published planning horizon.')
            continue
        icu_over += max(0, occ - cap) * config['icu_overflow_cost_per_bed_night']
    sc_cost = overtime * config['overtime_cost_per_minute'] + idle * config['idle_cost_per_minute'] + pacu_over + ward_over + icu_over
    scenario_costs[sid] = {'prob': pr, 'cost': sc_cost, 'overtime': overtime, 'idle': idle, 'pacu_over': pacu_over, 'ward_over': ward_over, 'icu_over': icu_over}
    components['expected_overtime'] += pr * overtime * config['overtime_cost_per_minute']
    components['expected_idle'] += pr * idle * config['idle_cost_per_minute']
    components['expected_pacu_overflow'] += pr * pacu_over
    components['expected_ward_overflow'] += pr * ward_over
    components['expected_icu_overflow'] += pr * icu_over

# check prob sum
if abs(prob_sum - 1.0) > 1e-9:
    add('schema/nullability and key coverage', 'scenarios.csv', 'scenario probabilities should sum to 1 for expected-cost accounting', prob_sum, 1.0, 'Normalize public scenario probabilities before scoring.')

# Search simple improvement opportunities for deferred cases: try greedy insertion into any block end preserving deterministic hard constraints and check objective delta with same cost approximation.
# We will only report if a concrete feasible insertion exists with negative deterministic cost delta; use same public approximation.

# helper to evaluate feasibility and approximate objective for a modified assignment of one deferred case appended at block end
from copy import deepcopy

def make_sol_map(solrows):
    return {r['case_id']: dict(r) for r in solrows}

base_sol_map = make_sol_map(sol)

# compact summary
print('VIOLATION_COUNT', len(violations))
for v in violations:
    print(v)
print('COMPONENTS', components)
print('SCENARIO_COSTS')
for sid in sorted(scenario_costs):
    print(sid, scenario_costs[sid])
print('OPEN_BLOCKS', sorted(open_blocks))
print('COVERAGE')
for fam in ['schema/nullability and key coverage','identifier domains','frozen/nonanticipative decisions','conservation and inventory','time, location, readiness, setup, and non-overlap','capacities and scenario derates','reserves/ramps','objective accounting']:
    print(fam, '=>', '; '.join(coverage[fam]['checked']) or 'none')
PY"

