        for fld in ['block_id','sequence','start_minute']:
            if r[fld] "'!= '"'':
                add('schema/nullability and key coverage',r['case_id'],f'deferred rows require blank {fld}',r[fld],'blank',f'Clear {fld}.')
    if dec == 'schedule' and r['case_id'] in cases:
        seq = None; st = None
        try: seq = int(r['sequence'])
        except: pass
        try: st = int(r['start_minute'])
        except: pass
        sched.append({'case_id': r['case_id'], 'block_id': r['block_id'], 'sequence': seq, 'start': st})

for x in sched:
    if x['block_id'] not in blocks:
        add('identifier domains',x['case_id'],'scheduled block_id must exist in or_blocks.csv',x['block_id'],'known block_id','Assign to a valid block or defer case.')
        continue
    c = cases[x['case_id']]
    if x['sequence'] is None or x['sequence'] <= 0:
        add('identifier domains',x['case_id'],'sequence must be a positive integer',x['sequence'],'>=1 integer','Use a positive in-block sequence.')
    if x['start'] is None:
        add('identifier domains',x['case_id'],'start_minute must be an integer minute',x['start'],'integer','Provide an integer start minute.')
    elif x['start'] < 0:
        add('identifier domains',x['case_id'],'start_minute must be nonnegative',x['start'],'>=0','Use minutes from day start.')
    s = surgeons.get(c['primary_surgeon'])
    if not s:
        add('identifier domains',x['case_id'],'primary surgeon must exist',c['primary_surgeon'],'known surgeon_id','Fix source or defer case.')
    else:
        if c['specialty'] not in set(s['specialties'].split('|')):
            add('identifier domains',x['case_id'],'primary surgeon must be credentialed for case specialty',c['specialty'],s['specialties'],'Use a credentialed surgeon/case pairing.')
    p = equip.get(c['equipment_pool'])
    if not p:
        add('identifier domains',x['case_id'],'equipment pool must exist',c['equipment_pool'],'known equipment_pool','Fix source or defer case.')
    else:
        if c['specialty'] not in set(p['allowed_specialties'].split('|')):
            add('identifier domains',x['case_id'],'case specialty must be eligible for listed equipment pool',c['specialty'],p['allowed_specialties'],'Use a compatible equipment pool.')

by_block = defaultdict(list)
for x in sched:
    if x['block_id'] in blocks and x['sequence'] is not None and x['start'] is not None:
        by_block[x['block_id']].append(x)

for bid, items in sorted(by_block.items()):
    b = blocks[bid]
    if len(items) > b['max_cases']:
        add('capacities and scenario derates',bid,'block case count cannot exceed max_cases',len(items),b['max_cases'],'Remove or reassign some cases from this block.')
    hi = sum(cases[x['case_id']]['high_acuity'] for x in items)
    if hi > b['max_high_acuity']:
        add('capacities and scenario derates',bid,'high-acuity case count cannot exceed max_high_acuity',hi,b['max_high_acuity'],'Move or defer a high-acuity case.')
    seqs = [x['sequence'] for x in items]
    for seq, n in Counter(seqs).items():
        if n > 1:
            add('time, location, readiness, setup, and non-overlap',bid,'sequences within a block must be unique',f'sequence {seq} used {n} times','all unique','Renumber cases uniquely inside the block.')
    inf = [x for x in items if cases[x['case_id']]['infection_flag']]
    if len(inf) > 1:
        add('time, location, readiness, setup, and non-overlap',bid,'at most one infection-control case may be placed in a block',len(inf),'<=1','Move all but one infection-control case out of the block.')
    ordered = sorted(items, key=lambda x: x['sequence'])
    for i,x in enumerate(ordered):
        c = cases[x['case_id']]
        allowed = set(b['allowed_specialties'].split('|'))
        if c['specialty'] not in allowed:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'case specialty must be accepted by block',c['specialty'],b['allowed_specialties'],'Move case to a compatible block.')
        if b['day'] < c['ready_day']:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'block day must be on/after ready_day',b['day'],f'>={c[\"ready_day\"]}','Move to a later block.')
        if c['pediatric'] and not b['pediatric_capable']:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'pediatric cases require pediatric-capable block',b['pediatric_capable'],1,'Move to a pediatric-capable block.')
        if c['needs_cardiac_monitoring'] and not b['cardiac_capable']:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'cardiac-monitoring cases require cardiac-capable block',b['cardiac_capable'],1,'Move to a cardiac-capable block.')
        if c['icu_need'] and not b['icu_direct']:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'ICU-direct cases require icu_direct block',b['icu_direct'],1,'Move to an ICU-direct block.')
        min_start = config['first_case_setup_minutes'] if i == 0 else ordered[i-1]['start'] + cases[ordered[i-1]['case_id']]['expected_duration_min'] + config['turnover_minutes']
        if x['start'] < min_start:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'planned start must respect setup/turnover after previous sequence',x['start'],f'>={min_start}','Delay this case or earlier cases.')
        finish = x['start'] + c['expected_duration_min']
        max_finish = b['regular_minutes'] + config['max_planned_overtime_minutes']
        if finish > max_finish:
            add('time, location, readiness, setup, and non-overlap',x['case_id'],'planned expected finish must stay within regular block time + overtime buffer',finish,f'<={max_finish}','Move, defer, or start earlier within valid sequence.')
    if inf:
        final_seq = max(x['sequence'] for x in items)
        for x in inf:
            if x['sequence'] "'!= final_seq:
                add('"'time, location, readiness, setup, and non-overlap',x['case_id'],'infection-control case must be final elective case in its block',x['sequence'],final_seq,'Place the infection-control case last or move it.')

ana_day = Counter()
sur_day = defaultdict(list)
for x in sched:
    if x['block_id'] not in blocks: continue
    c = cases[x['case_id']]
    day = blocks[x['block_id']]['day']
    ana_day[(day, c['anesthesia_type'])] += 1
    sur_day[(c['primary_surgeon'], day)].append(x)
    if str(day) not in surgeons[c['primary_surgeon']]['available_days'].split('|'):
        add('time, location, readiness, setup, and non-overlap',x['case_id'],'primary surgeon must be available on block day',day,surgeons[c['primary_surgeon']]['available_days'],'Move the case to an available day.')
for key, count in sorted(ana_day.items()):
