for (sid, day), items in sorted(sur_day.items()):
    s = surgeons[sid]
    total = sum(cases[x['case_id']]['expected_duration_min'] for x in items)
    if total > s['max_minutes_per_day']:
        add('capacities and scenario derates',f'{sid} day {day}','surgeon daily expected minutes cannot exceed max_minutes_per_day',total,s['max_minutes_per_day'],'Move/defer one of the surgeon’s cases that day.')
    if len(items) > s['max_cases_per_day']:
        add('capacities and scenario derates',f'{sid} day {day}','surgeon daily case count cannot exceed max_cases_per_day',len(items),s['max_cases_per_day'],'Move/defer one of the surgeon’s cases that day.')
    ints = sorted((x['start'], x['start'] + cases[x['case_id']]['expected_duration_min'], x['case_id'], x['block_id']) for x in items)
    for i in range(len(ints)):
        for j in range(i+1, len(ints)):
            if ints[j][0] < ints[i][1] and ints[j][3] "'!= ints[i][3]:
                add('"'time, location, readiness, setup, and non-overlap',f'{sid} day {day}','surgeon scheduled cases may not overlap across different rooms',f'{ints[i][2]}[{ints[i][0]},{ints[i][1]}) and {ints[j][2]}[{ints[j][0]},{ints[j][1]})','disjoint intervals','Shift or move one conflicting case.')

pool_day = defaultdict(list)
for x in sched:
    if x['block_id'] not in blocks: continue
    c = cases[x['case_id']]
    day = blocks[x['block_id']]['day']
    p = equip[c['equipment_pool']]
    pool_day[(c['equipment_pool'], day)].append((x['start'], x['start'] + c['expected_duration_min'] + p['turnaround_minutes'], x['case_id']))
for (pool, day), items in sorted(pool_day.items()):
    p = equip[pool]
    if len(items) > p['max_uses_per_day']:
        add('conservation and inventory',f'{pool} day {day}','equipment pool daily uses cannot exceed max_uses_per_day',len(items),p['max_uses_per_day'],'Move/defer one of the uses.')
    events = []
    for st,en,cid in items:
        events.append((st, 1, cid))
        events.append((en, -1, cid))
    active = 0
    for t, typ, cid in sorted(events, key=lambda z:(z[0], z[1])):
        active += typ
        if active > p['units']:
            add('conservation and inventory',f'{pool} day {day} minute {t}','parallel equipment use plus turnaround cannot exceed units',active,p['units'],'Delay or move a conflicting case.')
