scenario_summary = {}
for s in scenarios:
    overtime = idle = pacu_over = ward_over = icu_over = 0.0
    pacu_occ = Counter()
    ward_s = ward_occ.copy()
    icu_s = icu_occ.copy()
    if s['emergency_ward_night'] > 0 and s['emergency_ward_beds'] > 0:
        ward_s[(s['emergency_ward_night'], s['emergency_ward'])] += s['emergency_ward_beds']
    if s['emergency_icu_night'] > 0 and s['emergency_icu_beds'] > 0:
        icu_s[s['emergency_icu_night']] += s['emergency_icu_beds']
    for bid, items in by_block.items():
        b = blocks[bid]
        ordered = sorted(items, key=lambda x: x['sequence'])
        prev_finish = None
        for i,x in enumerate(ordered):
            c = cases[x['case_id']]
            dur = c['expected_duration_min'] * s[f'{c[\"anesthesia_type\"]}_factor'] + (s['high_acuity_extra_min'] if c['high_acuity'] else 0)
            start = x['start'] if i == 0 else max(x['start'], prev_finish + config['turnover_minutes'])
            finish = start + dur
            prev_finish = finish
            pstart, pend = finish, finish + c['pacu_minutes']
            for row in pacu:
                if row['day'] == b['day'] and max(pstart, row['bucket_start_minute']) < min(pend, row['bucket_end_minute']):
                    pacu_occ[(row['day'], row['bucket_start_minute'], row['bucket_end_minute'])] += 1
        finish = prev_finish
        if finish is None:
            continue
        if s['emergency_day'] == b['day'] and s['emergency_room'] == b['room']:
            # public data under-specifies insertion; take a minimal-finish interpretation for cost accounting and feasibility search.
            finish = max(finish, s['emergency_start_minute'] + s['emergency_minutes'])
        overtime += max(0.0, finish - b['regular_minutes'])
        idle += max(0.0, b['regular_minutes'] - finish)
    if s['emergency_day'] > 0 and s['emergency_pacu_minutes'] > 0:
        pstart = s['emergency_start_minute'] + s['emergency_minutes']
        pend = pstart + s['emergency_pacu_minutes']
        for row in pacu:
            if row['day'] == s['emergency_day'] and max(pstart, row['bucket_start_minute']) < min(pend, row['bucket_end_minute']):
                pacu_occ[(row['day'], row['bucket_start_minute'], row['bucket_end_minute'])] += 1
    for row in pacu:
        over = max(0, pacu_occ[(row['day'], row['bucket_start_minute'], row['bucket_end_minute'])] - row['capacity'])
        pacu_over += over * ((row['bucket_end_minute'] - row['bucket_start_minute'])/60.0) * config['pacu_overflow_cost_per_bed_hour']
    for key, occ in ward_s.items():
        cap = recovery.get(key)
        if cap is None:
            add('conservation and inventory',str(key),'ward occupancy must map to published capacity row',occ,'published capacity row','Keep occupancy inside the published horizon.')
        else:
