    scenario_summary[s['scenario_id']] = {'prob': s['probability'], 'overtime_min': round(overtime,3), 'idle_min': round(idle,3), 'pacu_over_cost': round(pacu_over,2), 'ward_over_cost': round(ward_over,2), 'icu_over_cost': round(icu_over,2)}
    components['expected_overtime'] += s['probability'] * overtime * config['overtime_cost_per_minute']
    components['expected_idle'] += s['probability'] * idle * config['idle_cost_per_minute']
    components['expected_pacu_overflow'] += s['probability'] * pacu_over
    components['expected_ward_overflow'] += s['probability'] * ward_over
    components['expected_icu_overflow'] += s['probability'] * icu_over

